package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsValidationException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create-owner request that is missing or blank in any required field
 * (firstName, lastName, address, city, telephone) before {@link BuildOwner} runs.
 *
 * <p>Binds the body here (the single {@code @RequestBody} for the pipeline) and republishes it
 * so later steps read it via {@code @Val}. On failure it throws
 * {@link OwnerFieldsValidationException}, which the escalation handler turns into a 400 whose
 * {@code errors} array lists each offending field.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws OwnerFieldsValidationException {
        List<String> errors = new ArrayList<>();
        requireText("firstName", request.getFirstName(), errors);
        requireText("lastName", request.getLastName(), errors);
        normalizeAddress(request, errors);
        requireText("city", request.getCity(), errors);
        requireText("telephone", request.getTelephone(), errors);
        normalizeTelephone(request, errors);
        OwnerEmail.normalize(request, errors);
        validatePostcode(request, errors);
        validateRegistrationDate(request, errors);
        if (!errors.isEmpty()) {
            throw new OwnerFieldsValidationException(errors);
        }
        validated.set(request);
    }

    /**
     * Normalizes the address to its canonical form (see {@link AddressNormalizer}) and stores it back
     * on the request so later steps persist and return it, and so household comparisons use it. The
     * required-field check happens here on the normalized value: an address that is blank after
     * normalization adds an {@code address} error (400).
     */
    private static void normalizeAddress(OwnerFieldsDto request, List<String> errors) {
        String normalized = AddressNormalizer.normalize(request.getAddress());
        if (normalized.isEmpty()) {
            errors.add("address");
            return;
        }
        request.setAddress(normalized);
    }

    /**
     * Normalizes the telephone to E.164 and stores it back on the request so later steps persist
     * and return it. A leading {@code +} and its country code are kept; otherwise country code
     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
     * Spaces, dashes and brackets are stripped, and the result must carry 8 to 15 digits after the
     * {@code +}. So {@code "0412 345 678"} becomes {@code "+61412345678"}. A number that cannot form
     * valid E.164 adds a {@code telephone} error (400). Skipped when the telephone is missing/blank,
     * which {@link #requireText} has already flagged.
     */
    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
        String telephone = request.getTelephone();
        if (telephone == null || telephone.isBlank()) {
            return;
        }
        String e164 = toE164(telephone);
        if (e164 == null) {
            errors.add("telephone");
            return;
        }
        request.setTelephone(e164);
    }

    /**
     * Returns the E.164 form of {@code telephone}, or {@code null} when it cannot form a valid one.
     */
    private static String toE164(String telephone) {
        String input = telephone.trim();
        boolean international = input.startsWith("+");
        // strip spaces, dashes and brackets from the remainder
        String cleaned = (international ? input.substring(1) : input).replaceAll("[\\s\\-()]", "");
        if (!cleaned.matches("\\d+")) {
            return null; // stray characters left over — not a phone number
        }
        String digits;
        if (international) {
            digits = cleaned;
        }
        else {
            // no country code: assume +61 and drop a single leading national '0'
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (digits.length() < 8 || digits.length() > 15) {
            return null;
        }
        if (!hasValidNationalLength(digits)) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * Enforces the national-number length required by the country code: {@code +61} needs 9 national
     * digits and {@code +1} needs 10. Other country codes carry no rule here, so only the general
     * E.164 8..15 total-digit bound applies to them.
     */
    private static boolean hasValidNationalLength(String digits) {
        if (digits.startsWith("61")) {
            return digits.length() - 2 == 9;
        }
        if (digits.startsWith("1")) {
            return digits.length() - 1 == 10;
        }
        return true;
    }

    /** Fixed city-to-region table backing the postcode range check. */
    private static final Map<String, String> CITY_REGIONS = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    /**
     * Validates the optional {@code postcode}. When absent the field is left untouched (optional, so
     * the request contract stays backward-compatible). When present it must be exactly four digits;
     * a malformed value adds a {@code postcode} error (400). For a city with a known region the
     * postcode must also fall within that region's range (NSW 2000-2099, VIC 3000-3099, QLD
     * 4000-4099); an out-of-range value adds a {@code postcode} error (400). A city with no known
     * region accepts any 4-digit postcode.
     */
    private static void validatePostcode(OwnerFieldsDto request, List<String> errors) {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return;
        }
        if (!postcode.matches("\\d{4}")) {
            errors.add("postcode");
            return;
        }
        String region = CITY_REGIONS.get(request.getCity());
        if (region == null) {
            return; // no known region for this city — any 4-digit postcode is accepted
        }
        int[] range = REGION_POSTCODES.get(region);
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            errors.add("postcode");
        }
    }

    /**
     * Validates the optional {@code registrationDate}. When absent the field is left untouched
     * (optional; the server defaults it later). When present it must not be later than the server's
     * current date — a future date adds a {@code registrationDate} error (400), so a client cannot
     * back-date the future.
     */
    private static void validateRegistrationDate(OwnerFieldsDto request, List<String> errors) {
        LocalDate registrationDate = request.getRegistrationDate();
        if (registrationDate == null) {
            return;
        }
        if (registrationDate.isAfter(LocalDate.now())) {
            errors.add("registrationDate");
        }
    }

    private static void requireText(String field, String value, List<String> errors) {
        if (value == null || value.isBlank()) {
            errors.add(field);
        }
    }
}
===== CheckIdentityUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The single duplicate check for the create-owner endpoint. It consolidates the former separate
 * telephone, email and household checks into one derived {@code identityKey}
 * ({@code normalizedTelephone|email|householdId}, see {@link OwnerIdentity}, also returned on the
 * owner) and rejects (409) when a new owner collides with an existing one on that identity.
 *
 * <p>The collision is driven by the normalized telephone (the leading, always-present component of
 * the key) together with the lower-cased email: two owners sharing both collide. Because the
 * telephone is part of the identity, two members of the same household (same {@code householdId})
 * with different telephones do <em>not</em> collide and are both allowed — a change from the former
 * household check, which rejected them regardless of telephone.
 *
 * <p>Runs after {@link ValidateOwnerFields} has normalized the telephone (E.164), email (lower-cased)
 * and address, and within the write transaction so the check and the insert see one consistent view.
 */
public class CheckIdentityUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String telephone = request.getTelephone();
        String email = normalizeEmail(request.getEmail());
        for (Owner existing : ownerRepository.findAll()) {
            boolean sameTelephone = telephone != null && telephone.equals(existing.getTelephone());
            boolean sameEmail = email.equals(normalizeEmail(existing.getEmail()));
            if (sameTelephone && sameEmail) {
                String householdId = OwnerIdentity.householdId(request.getLastName(), request.getPostcode());
                throw new DuplicateIdentityException(
                        OwnerIdentity.identityKey(telephone, request.getEmail(), householdId));
            }
        }
    }

    /** Lower-cased email, or {@code ""} when absent/blank, so the comparison is case-insensitive. */
    private static String normalizeEmail(String email) {
        return (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
    }
}
===== CheckHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects (409) a create-owner request that would join an existing household. Because the household
 * is now keyed on the computed {@code householdId} (a pure function of the normalized last name and
 * postcode, see {@link OwnerIdentity#householdId}), owners sharing a last name and postcode are the
 * same household. So a second such owner is a household duplicate unless it declares
 * {@code sharesHousehold}, in which case this block is bypassed and it is created as a declared
 * household member.
 *
 * <p>Runs after {@link CheckIdentityUnique} (so an exact identity collision is still a 409 even when
 * {@code sharesHousehold} is set) and within the write transaction, comparing against the owners
 * persisted so far. A missing postcode carries no household, so it never collides here.
 */
public class CheckHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // declared household member — bypass the block
        }
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // no postcode -> no household to collide with
        }
        String householdId = OwnerIdentity.householdId(request.getLastName(), postcode);
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(existing.getHouseholdId())) {
                throw new DuplicateHouseholdException(householdId);
            }
        }
    }
}
===== CheckCityCapacity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a create-owner request whose city already contains 50 or more owners, so the escalation
 * handler can respond 409. City is compared case-insensitively, matching how {@link AssignCustomerCode}
 * counts a city's owners. Runs within the same write transaction as the insert so the count reflects
 * only owners already persisted (excluding this new, not-yet-saved one), giving each city a hard cap
 * of 50 owners.
 */
public class CheckCityCapacity {

    private static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
                count++;
            }
        }
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city);
        }
    }
}
